blocks.source:
Subroutine A(x As Integer)
  x <- x + 5;
EndSubroutine

Subroutine B(x As Integer By Reference)
  x <- x + 5;
EndSubroutine

Algorithm Principal
  Define n As Integer <- 5;
  A(n);
  Write n;
  B(n);
  Write n;
EndAlgorithm

Subroutine Duplicar(saldo As Integer) As Integer
  Return saldo * 2;
EndSubroutine

Algorithm Tarjeta
  Define saldo As Integer <- 10;
  saldo <- Duplicar(saldo);
  Write saldo;
EndAlgorithm

Subroutine Duplicar(saldo As Integer By Reference)
  saldo <- saldo * 2;
EndSubroutine

Algorithm Tarjeta
  Define saldo As Integer <- 10;
  Duplicar(saldo);
  Write saldo;
EndAlgorithm
